"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["5303"],{3387(e,t,a){a.r(t),a.d(t,{metadata:()=>o,default:()=>p,frontMatter:()=>s,contentTitle:()=>l,toc:()=>h,assets:()=>c});var o=JSON.parse('{"id":"m11-autoscaling-gitops/quiz","title":"Quiz: Autoscaling & GitOps","description":"Check your grasp of the module: why CPU% is the wrong autoscaling signal for an LLM server, how KEDA turns a Prometheus metric into an HPA, scale-to-zero versus model cold-start, GitOps where the model version lives in git (the presence-cache lie and its fix, promote via PR, roll back via git revert), and the training guardrails that keep a batch job from starving the control plane.","source":"@site/docs/m11-autoscaling-gitops/quiz.mdx","sourceDirName":"m11-autoscaling-gitops","slug":"/m11-autoscaling-gitops/quiz","permalink":"/305-llmops/docs/m11-autoscaling-gitops/quiz","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Quiz: Autoscaling & GitOps"},"sidebar":"courseSidebar","previous":{"title":"Lab: Operate the Platform \u2014 Autoscale on Queue Depth, Promote Through Git, Train Under Guardrails","permalink":"/305-llmops/docs/m11-autoscaling-gitops/lab"},"next":{"title":"Deep Dive (Part 2)","permalink":"/305-llmops/docs/m11-autoscaling-gitops/deep-dive"}}'),n=a(4848),r=a(8453),i=a(7517);let s={sidebar_position:3,title:"Quiz: Autoscaling & GitOps"},l="Autoscaling & GitOps \u2014 Quiz",c={},h=[];function d(e){let t={code:"code",h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"autoscaling--gitops--quiz",children:"Autoscaling & GitOps \u2014 Quiz"})}),"\n",(0,n.jsxs)(t.p,{children:["Check your grasp of the module: why CPU% is the wrong autoscaling signal for an LLM server, how KEDA turns a Prometheus metric into an HPA, scale-to-zero versus model cold-start, GitOps where the model version lives in git (the presence-cache lie and its fix, promote via PR, roll back via ",(0,n.jsx)(t.code,{children:"git revert"}),"), and the training guardrails that keep a batch job from starving the control plane."]}),"\n",(0,n.jsx)(i.A,{questions:[{prompt:"You are wiring an autoscaler for the OpsMate model server. During an incident surge the queue backs up and users wait, but the pod's CPU% barely moves \u2014 so a CPU-based HPA never adds a replica. Why is CPU% the wrong signal, and what should you scale on?",options:[{text:"A queued request waits for a slot while consuming almost no CPU, so CPU% stays flat exactly when users are hurting. Scale on queue depth \u2014 llamacpp:requests_deferred \u2014 the count of requests parked because every slot is busy.",correct:!0,explanation:"Correct. llama.cpp decode pins about one core per in-flight request, and a deferred request burns ~0 CPU while the user waits. CPU% is blind to the queue; requests_deferred maps directly to user pain \u2014 the M10 gauge, now an autoscaler input."},{text:"CPU% is fine in principle, but the HPA needs a lower target percentage (e.g. 30%) to fire earlier.",correct:!1,explanation:"Lowering the target does not fix the blindness \u2014 a queued request contributes ~0 CPU, so no threshold on CPU% catches queueing. The signal itself is wrong, not its threshold."},{text:"You should scale on memory instead, since the model is memory-bound.",correct:!1,explanation:"Memory is roughly flat once the model is loaded (weights + KV budget), so it does not track load either. The load signal is the queue (requests_deferred), with concurrency and KV pressure as other honest LLM-native signals."},{text:"Autoscaling an LLM server is impossible on Kubernetes, so you must scale manually.",correct:!1,explanation:"It is entirely possible \u2014 you just need the right signal. KEDA scales the server fine on requests_deferred; the lab drives it 1 to 2 to 1 live."}]},{prompt:"You apply the ScaledObject and then run `kubectl get hpa`. You see keda-hpa-opsmate-model that you never wrote. What is the relationship between your ScaledObject and this HPA?",options:[{text:"KEDA reads your ScaledObject (with its Prometheus query), registers as an external-metrics source, and GENERATES a standard HPA that scales on that metric. The HPA is KEDA-owned \u2014 editing it by hand fights the operator.",correct:!0,explanation:"Correct. The ScaledObject is your declaration; KEDA turns it into a real v2 HPA and answers the HPA's metric queries from Prometheus. You manage the ScaledObject; KEDA manages the generated HPA."},{text:"They are unrelated \u2014 the HPA was left over from a previous module.",correct:!1,explanation:"The name keda-hpa-opsmate-model and its appearance right after you applied the ScaledObject give it away: KEDA created it from your ScaledObject. It is not leftover state."},{text:"The ScaledObject replaces the HPA API; there is no HPA involved anymore.",correct:!1,explanation:"The opposite \u2014 KEDA builds ON the HPA API. It generates a genuine HorizontalPodAutoscaler; the ScaledObject is a higher-level wrapper that produces one."},{text:"You must delete the generated HPA and manage scaling directly through the ScaledObject.",correct:!1,explanation:"Deleting it just makes KEDA recreate it \u2014 the generated HPA is how KEDA does the scaling. You reason about both objects; you do not remove the HPA."}]},{prompt:"Your teammate proposes setting minReplicaCount: 0 (scale-to-zero) on the model server to save resources when idle. For OpsMate \u2014 an interactive on-call assistant \u2014 why is that the wrong call, and where would scale-to-zero be right?",options:[{text:"A model server cold start is image pull + model LOAD (minutes), not the seconds a stateless web pod takes. Scaling to zero means the next user waits minutes for the first answer. Keep 1 warm for an interactive service; scale-to-zero fits rare/batch endpoints where a cold start is acceptable.",correct:!0,explanation:"Correct. The cold-start cost for an LLM is dominated by loading the weights into memory, which is minutes on the 8 GB path. For interactive traffic that is unacceptable, so min 1. A nightly batch-scoring endpoint that no one waits on is a fine scale-to-zero candidate."},{text:"Scale-to-zero is never possible with KEDA, so the proposal cannot be implemented.",correct:!1,explanation:"KEDA does support scale-to-zero (idleReplicaCount: 0). The point is not that it is impossible \u2014 it is that a minutes-long model cold start makes it wrong for an interactive service."},{text:"It is the right call \u2014 model servers cold-start in milliseconds like any pod.",correct:!1,explanation:"They do not. A stateless web pod starts fast, but a model server must load hundreds of MB to GB of weights before it can answer anything \u2014 the cold start is minutes, which is the whole reason to keep one warm."},{text:"Scale-to-zero would corrupt the model on the PVC.",correct:!1,explanation:"Scaling to zero just removes the running pod; the model bytes on the PVC are untouched. The cost is cold-start latency on the next request, not data loss."}]},{prompt:"You promote OpsMate by bumping the ModelKit tag from 1.0.0 to 1.0.0-candidate in the git env repo via a PR. Argo CD syncs, the pod rolls, git says candidate \u2014 but users still get the old model's answers. What happened, and what is the fix?",options:[{text:"The initContainer's idempotency guard saw a GGUF already on the PVC and SKIPPED the unpack, so the server kept serving the old bytes under the new tag. Fix it by making the unpack path carry the tag (per-tag dirs like /model/kits/<tag>/...) so a new tag is a new directory the guard has never seen.",correct:!0,explanation:"Correct \u2014 the presence-cache lie. The guard that makes scale-out fast (skip the unpack if the model is present) makes naive promotion a lie (skip the unpack, serve old bytes). Per-tag unpack dirs make the tag part of the path, so a new tag actually unpacks. And the fix goes through git, not kubectl edit."},{text:"Argo CD failed to sync; re-running the sync would have served the new model.",correct:!1,explanation:"Argo synced fine and the pod rolled to the new spec \u2014 the deployment references candidate. The problem is downstream of the sync: the init skipped the unpack, so the correct spec still loads the old file."},{text:"The PR was never merged, so git still points at 1.0.0.",correct:!1,explanation:"Git does say candidate (the pod rolled to the new spec). The lie is not in git \u2014 it is that the on-disk bytes never changed because the unpack was skipped."},{text:"You should fix it fast with kubectl edit on the running deployment.",correct:!1,explanation:"Never edit a GitOps-managed object with kubectl \u2014 the next Argo sync overwrites you. The fix (per-tag dirs) must land as a commit in the env repo so it survives reconciliation."}]},{prompt:"The candidate misbehaves and you need to roll OpsMate back to 1.0.0 immediately. Which statements about the GitOps rollback are true? (Select all that apply.)",options:[{text:"Rollback is git revert in the env repo \u2014 no special tooling. Argo CD reconciles the reverted state back onto the cluster.",correct:!0,explanation:"Correct. Because desired state (including the model version) lives in git, undoing a promotion is a git operation. Argo sees the revert and reconciles."},{text:"Reverting the PR merge commit needs `git revert -m 1` because a merge commit has two parents and you must name the mainline one.",correct:!0,explanation:"Correct \u2014 a real git gotcha. A plain git revert of a merge commit fails asking which parent is mainline; -m 1 selects the pre-merge main line."},{text:"The rollback serves fast because the old 1.0.0 bytes never left the PVC, so the init skips the unpack again.",correct:!0,explanation:"Correct \u2014 and it is the symmetry lesson. The same presence-cache that LIED during promotion (old bytes under a new label) makes ROLLBACK instant (old bytes still present, no re-fetch). Same mechanism, opposite value."},{text:"You should roll back by running kubectl rollout undo, bypassing git entirely.",correct:!1,explanation:"False for a GitOps-managed object. kubectl rollout undo changes live state that Argo will immediately reconcile back to what git says. The rollback has to be in git (git revert), or the next sync re-applies the candidate."}],multiSelect:!0},{prompt:'You submit the fine-tune as an Argo Workflow on the single-node 8 GB cluster. Why does the training pod carry a `limits.cpu: "2"`, and why do you drain serving (KEDA paused-replicas: "0" + scale observability to 0) before running it?',options:[{text:"An uncapped training pod can drive node CPU so high that it starves the kube-apiserver \u2014 kubectl stops working and recovery needs break-glass on the node. The CPU limit protects the CONTROL PLANE (ordinary processes on the same node), and draining serving keeps one heavyweight running at a time on a shared node.",correct:!0,explanation:"Correct \u2014 the starvation post-mortem. The control plane competes for the same CPU as your pods; a batch job with no limit can wedge it. The limit is control-plane protection, not just pod health, and draining serving frees the node's memory for the trainer. Full-fidelity training is the 16 GB / host path."},{text:"The CPU limit makes training faster by giving it dedicated cores.",correct:!1,explanation:"A limit is a ceiling, not a reservation \u2014 it caps CPU, it does not speed training up. Its purpose is to stop the pod from crowding out the control plane, which it does at some cost to training speed."},{text:"Draining serving is only for saving money, not for stability.",correct:!1,explanation:"On the 8 GB single-node path it is about resources and stability: one heavyweight at a time so the trainer has the node's memory and does not compete with serving. KEDA's paused-replicas annotation is the drain lever."},{text:"You do not actually need the limit; the scheduler prevents any pod from starving the node.",correct:!1,explanation:"The scheduler places pods by their requests, but without a limit a pod can burst well past its request and starve co-located processes \u2014 including the control plane. The spike proved exactly this failure; the limit is what prevents it."}]},{prompt:"During the spike, an uncapped training pod pinned every core and the kube-apiserver was starved: `kubectl scale --replicas=0` on the training pod just hung. You are on the node. Which recovery moves are sound, and why? (Select all that apply.)",options:[{text:"`crictl stop` against containerd on the node \u2014 it bypasses the apiserver and talks to the runtime directly, so it can work when kubectl cannot (though under extreme pressure even it returned DeadlineExceeded).",correct:!0,explanation:"Correct. crictl is one level down the break-glass ladder: it talks to containerd directly, not through the starved apiserver. In a milder incident it is your recovery level; in this spike the runtime itself was starved enough that crictl stop timed out too."},{text:"`pkill -9` the training process by name on the node \u2014 the floor of the ladder, depending on nothing the starvation broke: no apiserver, no runtime API, just the kernel killing a PID.",correct:!0,explanation:"Correct. pkill is the last level and the one that worked, precisely because it needs neither the apiserver nor the container runtime \u2014 just the kernel. It is the break-glass of last resort."},{text:"Retry `kubectl scale --replicas=0` a few more times \u2014 the apiserver will eventually answer once a request gets through.",correct:!1,explanation:"This is the trap. kubectl is a client of the very apiserver you starved; its TLS handshakes are timing out. You cannot fix a starved control plane with the tool that depends on it \u2014 hammering it just hangs again."},{text:"Add a `limits.cpu` to the training pod spec via `kubectl edit` to throttle it immediately.",correct:!1,explanation:"kubectl edit also goes through the starved apiserver, so it hangs like every other kubectl call \u2014 and even if it landed, a CPU limit change does not throttle an already-running container mid-crisis. The limit is a preventive fix for the NEXT run, applied after you kill this one from the node."}],multiSelect:!0},{prompt:'You drained serving for training by setting `autoscaling.keda.sh/paused-replicas: "0"` on the ScaledObject. Training is done and you want autoscaling back \u2014 someone suggests setting the annotation to `"1"` to restore one warm replica. Why is that wrong, and what actually resumes autoscaling?',options:[{text:'KEDA treats ANY paused-replicas value \u2014 including "1" \u2014 as "paused": it pins the deployment at that count and does not regenerate the HPA. You must REMOVE the annotation entirely; only then does KEDA resume normal reconciliation and re-create keda-hpa-opsmate-model.',correct:!0,explanation:'Correct. paused-replicas is a pause button, not a replica dial. "1" is still paused \u2014 it holds the count fixed and leaves the generated HPA gone. Deleting the annotation (kubectl annotate ... paused-replicas-) is what resumes scaling and rebuilds the HPA.'},{text:'Setting it to "1" is correct \u2014 KEDA reads "1" as the new minReplicaCount and resumes scaling from there.',correct:!1,explanation:"It does not. paused-replicas is not minReplicaCount; any value pins the deployment and suspends reconciliation. The floor lives in the ScaledObject spec, not this annotation."},{text:"You should delete and re-apply the whole ScaledObject to reset it.",correct:!1,explanation:"Unnecessary and heavier than needed \u2014 the ScaledObject is fine, it is just paused by an annotation. Removing the one annotation resumes it cleanly; recreating the object is a bigger hammer for no reason."},{text:"Restart the KEDA operator so it re-reads the annotation as a resume signal.",correct:!1,explanation:'Restarting the operator changes nothing \u2014 it will read the same "paused" annotation and keep the target pinned. The annotation, not the operator process, is what holds scaling paused.'}]},{prompt:"You applied a ScaledObject; `keda-hpa-opsmate-model` appeared. Walking the KEDA machinery from the Deep Dive, how does that generated HPA actually get a queue-depth number to compare against its threshold?",options:[{text:"KEDA registers an APIService for external.metrics.k8s.io; the HPA (a real autoscaling/v2 object with a type: External metric source) asks the aggregation layer for the value, which routes to KEDA's metrics-server, which runs sum(llamacpp:requests_deferred) against Prometheus and returns the number.",correct:!0,explanation:"Correct. KEDA IS the external-metrics adapter \u2014 no prometheus-adapter needed. The HPA does the ordinary arithmetic (current/target); KEDA answers its metric query by hitting Prometheus. That is why deferred=12 against threshold=2 shows as 12/2 and scales out."},{text:"The ScaledObject scrapes Prometheus itself and writes the replica count directly onto the Deployment, so no HPA is really involved.",correct:!1,explanation:"The opposite \u2014 KEDA builds ON the HPA API. keda-hpa-opsmate-model is a genuine v2 HPA you can kubectl get and inspect; KEDA feeds it via external metrics, it does not bypass it."},{text:"KEDA installs prometheus-adapter and a PromQL recording rule that the HPA reads through the standard metrics pipeline.",correct:!1,explanation:"No prometheus-adapter and no recording-rule wiring are involved \u2014 that is precisely what KEDA saves you. KEDA itself is the purpose-built external-metrics adapter for external.metrics.k8s.io."},{text:"The HPA polls the model pod's /metrics endpoint directly for requests_deferred.",correct:!1,explanation:"The HPA never scrapes pods \u2014 it asks the external-metrics API. Prometheus (M10) scrapes /metrics; KEDA queries Prometheus; the HPA queries KEDA. The pod's endpoint is upstream of two hops, not something the HPA reads."}]},{prompt:"You fixed the presence-cache lie with per-tag unpack dirs, and the candidate pod then CrashLooped with `failed to open GGUF file .../qwen3-0.6b-q8_0.gguf (No such file or directory)`. A peek pod shows the candidate dir actually holds `opsmate-tuned-q8_0.gguf`. What is going on, and what is the fix?",options:[{text:"The candidate kit ships its GGUF under a different filename than the base kit \u2014 the M9 per-kit filename echo. The unpack landed the real file; the server and guard are still keyed on the old name, so the server opens a path that does not exist. Fix it in git: point the guard and the server -m at the candidate's real filename.",correct:!0,explanation:"Correct \u2014 Exhibit B. Per-tag dirs made the unpack happen; now the filename mismatch surfaces. The candidate GGUF is opsmate-tuned-q8_0.gguf, not qwen3-0.6b-q8_0.gguf, so the -m path is wrong. The fix is a commit that updates the guard and -m to the real name \u2014 through git, like every other change here."},{text:"The unpack failed and left the directory empty, so the server has nothing to open.",correct:!1,explanation:"The peek pod proves the opposite \u2014 the dir holds opsmate-tuned-q8_0.gguf, a real unpacked file. The unpack succeeded; the crash is a filename MISMATCH between what was unpacked and what the server was told to open."},{text:"The per-tag dir fix was wrong and should be reverted \u2014 go back to the single shared model directory.",correct:!1,explanation:"The per-tag dir fix is correct and necessary (it is what made the candidate actually unpack). Reverting it would restore the presence-cache lie. Exhibit B is a separate filename issue layered on top, fixed by pointing -m at the right name."},{text:"You should kubectl exec into the crashing container and rename the file to match the server's -m flag.",correct:!1,explanation:"You cannot exec into a crash-looping container (no running process), which is exactly why the lab uses a throwaway peek pod to read the PVC. And even if you could, an ad-hoc rename is not in git \u2014 the next Argo sync would not preserve it. The fix must be a commit."}]},{prompt:"The training workflow's `.status.phase` reads `Error` with `workflowtaskresults.argoproj.io is forbidden`, yet the loss printed two steps and an adapter was saved. Before you re-run the expensive job, what does the Deep Dive tell you to check, and what does the Error actually mean?",options:[{text:"Read the main container's exit code in containerStatuses \u2014 it is ground truth for whether training ran. Here main exited 0 (training succeeded); the phase says Error only because Argo's executor sidecar lacked RBAC to write workflowtaskresults back, so the controller could not confirm the result. Apply the executor Role/RoleBinding and re-submit.",correct:!0,explanation:"Correct \u2014 the phase-vs-containerStatuses lesson. The phase reports the WRAPPER's bookkeeping (the executor could not report back), not the job. The main container's exit 0 is the truth. The fix is granting workflowtaskresults create/patch to the workflow SA, not re-running the training."},{text:"Trust the phase \u2014 Error means the training failed, so delete the adapter and re-run from scratch.",correct:!1,explanation:"This is exactly the mistake the section warns against: re-shipping a package already on the doorstep. The phase reflects the executor's failed result-write, not the training. The main container exited 0 \u2014 checking containerStatuses saves you a wasted re-run."},{text:"The forbidden error means the training pod could not read the base weights, so mount them read-write and re-run.",correct:!1,explanation:"The forbidden error is about workflowtaskresults (Argo's result CRD), not the model weights \u2014 it is an executor RBAC problem, not a data-access one. The base weights mounted fine; training ran to completion."},{text:"Raise the training pod's CPU limit so the executor gets enough cycles to write results in time.",correct:!1,explanation:"This is an RBAC authorization failure (forbidden), not a starvation/timeout one. More CPU does not grant the SA permission to create workflowtaskresults; only the Role/RoleBinding does."}]},{prompt:'Before the training window you cap the training pod at `limits.cpu: "2"` and pause serving \u2014 yet the lab also has you scale KEDA, Argo CD, gitea, and observability down to 0. If the training pod is already CPU-capped and memory-limited, why drain the idle control planes too, and what happens if you skip it?',options:[{text:"The CPU cap protects the control plane from CPU starvation, but memory is a separate axis: the resident memory of KEDA + Argo CD + gitea + the workflow controller stacks on the training pod's fp32 footprint and can push the single node past its memory ceiling. When it does, the kernel OOM-kills the kind NODE container itself (Exited 137) and the whole cluster blips. Draining the idle, stateless, recreatable control planes frees that memory; Argo reconverges from git when you bring them back.",correct:!0,explanation:"Correct. This is the node-level OOM, distinct from the CPU-starvation post-mortem. The CPU limit handles CPU; memory is its own ceiling on the 8 GB node. The control planes are tenants too \u2014 idle during a batch window \u2014 so parking them gives the trainer the node's memory. Because desired state is in git, Argo CD reconverges by itself on restore."},{text:"Skipping the drain only slows training; the node never actually goes down because the memory limit on the training pod protects it.",correct:!1,explanation:"The training pod's memory limit protects only the pod (it would be OOM-killed cleanly at its own ceiling). It does nothing for the NODE's total memory, which the resident control planes also consume \u2014 that is what tips the node over and gets the node container OOM-killed."},{text:"You drain them to save money on the cloud bill, not for stability.",correct:!1,explanation:'On the single 8 GB node this is about memory headroom and node survival, not cost. Leave them resident and the node itself gets OOM-killed, taking the cluster with it \u2014 the exact failure "one heavyweight at a time" exists to prevent.'},{text:"Draining is risky because Argo CD and gitea lose their state when scaled to 0, so you must back them up first.",correct:!1,explanation:"They do not lose state \u2014 the control planes are stateless and recreatable, and the source of truth (the model version) lives in git, which is untouched. That is the whole point: you park the controllers, not the truth, and Argo reconverges from git on restore."}]}]})]})}function p(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},7517(e,t,a){a.d(t,{A:()=>i});var o=a(4848),n=a(6540);function r({q:e,state:t,onToggle:a}){return(0,o.jsxs)("div",{className:"question_QpiT",children:[(0,o.jsx)("p",{className:"prompt_TqRJ",children:e.prompt}),e.multiSelect&&(0,o.jsx)("p",{className:"hint_e_F7",children:"(select all that apply)"}),(0,o.jsx)("ul",{className:"options_X9pq",children:e.options.map((e,n)=>{let r=t.selected.has(n),i="option_qGol";return t.checked?e.correct?i+=" correct_LYA5":r&&(i+=" incorrect_kRFc"):r&&(i+=" chosen_H3WG"),(0,o.jsxs)("li",{children:[(0,o.jsxs)("button",{type:"button",className:i,disabled:t.checked,onClick:()=>a(n),children:[(0,o.jsx)("span",{className:"marker_vN_w",children:r?"\u25CF":"\u25CB"})," ",e.text]}),t.checked&&(r||e.correct)&&e.explanation&&(0,o.jsx)("p",{className:"explanation_HBZ0",children:e.explanation})]},n)})})]})}function i({questions:e}){let[t,a]=(0,n.useState)(e.map(()=>({selected:new Set,checked:!1}))),s=t.every(e=>e.checked),l=t.filter((t,a)=>{var o,n;let r;return o=e[a],n=t.selected,r=o.options.map((e,t)=>e.correct?t:-1).filter(e=>e>=0),o.multiSelect?n.size===r.length&&[...n].every(e=>o.options[e].correct):1===n.size&&r.includes([...n][0])}).length;return(0,o.jsxs)("div",{className:"quiz_I014",children:[e.map((n,i)=>(0,o.jsx)(r,{q:n,state:t[i],onToggle:t=>a(a=>a.map((a,o)=>{if(o!==i)return a;let n=new Set(a.selected);return e[i].multiSelect?n.has(t)?n.delete(t):n.add(t):(n.clear(),n.add(t)),{...a,selected:n}}))},i)),(0,o.jsxs)("div",{className:"actions_XUwt",children:[(0,o.jsx)("button",{type:"button",className:"check_wZ2j",onClick:()=>a(e=>e.map(e=>({...e,checked:!0}))),children:"Check answers"}),(0,o.jsx)("button",{type:"button",className:"resetBtn_JHSa",onClick:()=>a(e.map(()=>({selected:new Set,checked:!1}))),children:"Reset"}),s&&(0,o.jsxs)("span",{className:"score_AN7p",children:["Score: ",l," / ",e.length]})]})]})}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>s});var o=a(6540);let n={},r=o.createContext(n);function i(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);